
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_th3_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_th3", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.514487043623694e+00, -4.421830160874461e+00, -4.292356892010750e+00, -4.113773153405303e+00, -3.872069449107200e+00, -3.553864124506560e+00, -3.151609200431880e+00, -2.672603094319538e+00, -2.149810832036999e+00, -1.637721109797389e+00, -1.130668985037979e+00, -7.515368718450660e-01, -6.510378475907490e-01, -5.348089429766970e-01, -3.928977702629270e-01, -2.598277227740972e-01, -1.529730273181444e-01, -7.384140203195477e-02, -2.675750814522851e-02, -4.921671241534170e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


